INSERT INTO knowledge_card_revisions (topic_id, card_id, version, content) VALUES
  ('A03', 'KP-A03-01', 1, '{"overview":"危机题最重要的是顺序：先保人，再走程序；再联动资源；稳定局面；最后恢复和复盘。","points":[{"id":"a03-p1","cue":"保","summary":"生命优先","detail":"保：生命和人身安全优先，迅速控制直接风险。"},{"id":"a03-p2","cue":"报","summary":"启动预案","detail":"报：启动预案并按制度及时报告，保存必要信息。"},{"id":"a03-p3","cue":"联","summary":"多方协作","detail":"联：联动家长、心理专业人员、医疗机构及必要部门。"},{"id":"a03-p4","cue":"稳","summary":"情绪秩序","detail":"稳：稳定学生、班级、教师和家长情绪，恢复秩序。"},{"id":"a03-p5","cue":"复","summary":"跟踪复盘","detail":"复：持续跟踪、恢复支持、复盘原因、完善制度和预案。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A13', 'KP-A13-01', 1, '{"overview":"科学教育不是多上几节科学课，而是让学生真正经历“提出问题—动手探究—用证据解释—解决真实问题”的过程，并用教师、空间、评价和社会资源把它撑起来。","points":[{"id":"a13-p1","cue":"课","summary":"探究课程","detail":"课：完善课程，强化实验、探究、项目式、跨学科学习。"},{"id":"a13-p2","cue":"师","summary":"教师支持","detail":"师：加强科学教师队伍，引入专业力量。"},{"id":"a13-p3","cue":"地","summary":"学习空间","detail":"地：实验室、科创空间、科普场馆、高校科研资源。"},{"id":"a13-p4","cue":"评","summary":"过程评价","detail":"评：重探究过程、实践、问题解决和创新，不唯分数。"},{"id":"a13-p5","cue":"外","summary":"社会资源","detail":"外：家校社、高校、科研院所和社会科技资源协同。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A21', 'KP-A21-01', 1, '{"overview":"AI进学校不是“买一套系统”就叫转型。真正的数字化转型要同时改变教、学、管、评，并补上人的数字素养和安全伦理。","points":[{"id":"a21-p1","cue":"人","summary":"数字素养","detail":"人：先培养“会用AI、更会思考的人”。提升学生、教师和管理者的数字素养与人工智能素养，强调提出问题、判断信息、解决复杂问题和创新，而不是让AI替代思考。"},{"id":"a21-p2","cue":"课","summary":"课程资源","detail":"课：更新课程内容和数字资源，开好人工智能相关课程，建强用好国家智慧教育公共服务平台，让优质资源更普惠、更可共享。"},{"id":"a21-p3","cue":"教","summary":"教师赋能","detail":"教：AI支持备课、资源生成、学情分析、精准教学和教师专业发展，但教师仍承担育人责任与专业判断。"},{"id":"a21-p4","cue":"学","summary":"自主探究","detail":"学：支持个性化、探究式、项目式学习和大规模因材施教，让学生从“得到答案”转向“提出问题、验证证据、解决问题”。"},{"id":"a21-p5","cue":"管","summary":"数据治理","detail":"管：把数据变成治理能力，形成“采集—治理—分析—决策—反馈”闭环，用于规划、资源配置、风险预警和公共服务。"},{"id":"a21-p6","cue":"评","summary":"多元评价","detail":"评：用AI和数据支持过程评价、增值评价、综合评价与科学决策，避免“唯分数”“唯数据”“唯算法”。"},{"id":"a21-p7","cue":"安","summary":"安全伦理","detail":"安：强化网络安全、数据安全、个人信息保护、算法与人工智能伦理；同时关注数字鸿沟，避免技术扩大教育不均衡。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A04', 'KP-A04-01', 1, '{"overview":"组织题的本质不是记结构名称，而是看：谁有权、谁负责、信息怎么走、部门怎么协作、谁来监督。","points":[{"id":"a04-p1","cue":"权","summary":"决策授权","detail":"权：谁有决策权，授权到哪里。"},{"id":"a04-p2","cue":"责","summary":"结果责任","detail":"责：谁对结果负责，避免责任真空或重叠。"},{"id":"a04-p3","cue":"沟","summary":"信息流动","detail":"沟：信息能否及时、准确地上下左右流动。"},{"id":"a04-p4","cue":"协","summary":"部门合作","detail":"协：跨部门、跨年级、跨专业能否合作。"},{"id":"a04-p5","cue":"督","summary":"监督纠偏","detail":"督：是否有监督、反馈和纠偏机制。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A05', 'KP-A05-01', 1, '{"overview":"层级撤了不等于管理功能消失。真正的问题通常是：人撤了，但原来承担的协调、决策、责任功能没有重新安排。","points":[{"id":"a05-p1","cue":"权","summary":"明确权责","detail":"权：重新明确权责，原中间层必要职能必须有人承接。"},{"id":"a05-p2","cue":"决","summary":"决策规则","detail":"决：建立新的分层决策规则：什么事谁定、按什么程序定。"},{"id":"a05-p3","cue":"协","summary":"协作机制","detail":"协：建立项目组、年级共同体等协作机制，并提升协同能力。"},{"id":"a05-p4","cue":"改","summary":"动态调整","detail":"改：改革不能一刀切，边运行、边评价、边调整。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A09', 'KP-A09-01', 1, '{"overview":"评价不是为了“打分结束”，而是为了做决定和改进。先问：为什么评？（目的）谁来评？（主体）评什么？（内容）怎么评？（方法）评完怎么办？（改进和做决策）","points":[{"id":"a09-p1","cue":"目","summary":"评价目的","detail":"目：明确评价目的：诊断、改进、决策还是结果判断。"},{"id":"a09-p2","cue":"谁","summary":"评价主体","detail":"谁：确定评价主体，可单一也可多主体。"},{"id":"a09-p3","cue":"啥","summary":"评价内容","detail":"啥：明确指标和评价内容。"},{"id":"a09-p4","cue":"法","summary":"工具方法","detail":"法：选择资料、工具和方法，兼顾过程与结果。"},{"id":"a09-p5","cue":"改","summary":"反馈改进","detail":"改：把结果用于反馈、改进和后续决策。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A20', 'KP-A20-01', 1, '{"overview":"评价改革的核心不是“少考试”，而是从只看一次结果，转向看全面发展、过程变化、增值成长，并让评价结果真正用于改进。","points":[{"id":"a20-p1","cue":"全","summary":"全面素养","detail":"全：评价内容更全面，关注德智体美劳和综合素养，不唯分数。"},{"id":"a20-p2","cue":"过","summary":"关注过程","detail":"过：重视过程评价，关注学习、教学和项目实施过程。"},{"id":"a20-p3","cue":"增","summary":"起点成长","detail":"增：看起点和成长幅度，重视增值评价。"},{"id":"a20-p4","cue":"多","summary":"多元证据","detail":"多：主体、证据和方法多元，可结合数据、观察、作品、反馈等。"},{"id":"a20-p5","cue":"改","summary":"反馈改进","detail":"改：评价结果必须用于反馈、诊断、改进和决策，而非只排名。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A01', 'KP-A01-01', 1, '{"overview":"教师不积极，先别急着喊“奉献”。先问：他的基本保障、公平感、被认可、成长机会、发挥平台和工作环境出了什么问题？","points":[{"id":"a01-p1","cue":"钱","summary":"公平保障","detail":"钱：基本待遇、制度保障和公平感。不是简单“发钱”，而是让教师感到付出与回报基本合理。"},{"id":"a01-p2","cue":"认","summary":"认可成就","detail":"认：精神认可、荣誉、信任和成就感。努力要被看见。"},{"id":"a01-p3","cue":"长","summary":"专业成长","detail":"长：培训、教研、进修、晋升和职业发展，让教师看见成长路径。"},{"id":"a01-p4","cue":"台","summary":"发挥平台","detail":"台：课程、课题、展示、项目、管理参与等平台，让能力有地方发挥。"},{"id":"a01-p5","cue":"境","summary":"支持文化","detail":"境：公平、尊重、合作、支持性的学校文化，减少内耗。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A02', 'KP-A02-01', 1, '{"overview":"规划不是写一份漂亮文件，而是回答五个常识问题：现在在哪？未来去哪？怎么去？拿什么去？怎么知道走对了？","points":[{"id":"a02-p1","cue":"看","summary":"分析内外","detail":"看：看内部优势/问题与外部机会/挑战，可与SWOT联系。"},{"id":"a02-p2","cue":"定","summary":"愿景目标","detail":"定：确定愿景、使命和阶段性目标。"},{"id":"a02-p3","cue":"做","summary":"行动计划","detail":"做：把目标转成策略、项目和行动计划。"},{"id":"a02-p4","cue":"配","summary":"资源责任","detail":"配：配置人员、经费、时间和资源，明确责任。"},{"id":"a02-p5","cue":"评","summary":"监测调整","detail":"评：监测、评价、反馈和调整，形成闭环。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A14', 'KP-A14-01', 1, '{"overview":"安全管理不能只在出事后救火。真正完整的逻辑是：平时预防、经常排查、出事处置、联动资源、事后复盘。","points":[{"id":"a14-p1","cue":"防","summary":"风险预防","detail":"防：制度、教育、培训、演练和风险预防。"},{"id":"a14-p2","cue":"查","summary":"排查隐患","detail":"查：常态排查设施、人员、食品、心理、网络等隐患。"},{"id":"a14-p3","cue":"处","summary":"迅速处置","detail":"处：突发事件迅速处置，生命安全优先。"},{"id":"a14-p4","cue":"联","summary":"外部协作","detail":"联：家长、公安、消防、医疗、社区等联动。"},{"id":"a14-p5","cue":"复","summary":"复盘整改","detail":"复：恢复、调查、复盘、整改，防止重复发生。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A22', 'KP-A22-01', 1, '{"overview":"这道题最容易混淆的地方是：不是“书记管政治、校长管教学，各干各的”，而是党组织全面领导、校长依法负责教育教学和行政管理，同时通过分工、议事和沟通机制协调运行。","points":[{"id":"a22-p1","cue":"党领","summary":"全面领导","detail":"党领：党组织全面领导学校工作，把方向、管大局、作决策、抓班子、带队伍、保落实。"},{"id":"a22-p2","cue":"校责","summary":"依法履职","detail":"校责：校长在党组织领导下依法依规行使职权，全面负责教育教学和行政管理。"},{"id":"a22-p3","cue":"集决","summary":"集体决策","detail":"集决：重大问题坚持集体领导、民主集中、个别酝酿、会议决定；重大事项依法科学民主决策。"},{"id":"a22-p4","cue":"分工","summary":"职责边界","detail":"分工：明确领导班子职责、议事事项和权责边界，执行集体决定。"},{"id":"a22-p5","cue":"协同","summary":"沟通合作","detail":"协同：建立书记校长定期沟通、党政分工合作、协调运行机制。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A23', 'KP-A23-01', 1, '{"overview":"这几个词不要分开背。把它们看成同一个国家战略问题：教育负责育人和人才供给，科技提供创新牵引，人才把知识与技术变成发展能力；三者必须围绕国家战略协同起来。","points":[{"id":"a23-p1","cue":"育","summary":"教育基础","detail":"育：教育是基础：提高人才自主培养质量，促进全面发展和公平优质。"},{"id":"a23-p2","cue":"科","summary":"科技牵引","detail":"科：科技是牵引：强化科技教育、创新能力和国家战略科技支撑。"},{"id":"a23-p3","cue":"才","summary":"人才培养","detail":"才：人才是关键：培养拔尖创新人才和国家战略急需人才。"},{"id":"a23-p4","cue":"融","summary":"一体统筹","detail":"融：教育、科技、人才一体统筹，推动学校、高校、科研机构、企业和社会资源协同。"},{"id":"a23-p5","cue":"强","summary":"强国目标","detail":"强：最终服务教育强国和中国式现代化，提高教育质量、支撑国家战略和民生需求。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A06', 'KP-A06-01', 1, '{"overview":"改革失败常常不是“老师不支持改革”这么简单，而是五个环节没打通：不知道为什么改、不愿改、不会改、没条件做、做了没人根据反馈调整。","points":[{"id":"a06-p1","cue":"知","summary":"讲清改革","detail":"知：讲清改革必要性、目标和现实问题，减少信息不对称。"},{"id":"a06-p2","cue":"愿","summary":"参与回应","detail":"愿：让教师参与讨论和决策，回应利益、工作量和公平感。"},{"id":"a06-p3","cue":"能","summary":"培训支持","detail":"能：提供培训、工具、资源和同伴支持。"},{"id":"a06-p4","cue":"做","summary":"试点推进","detail":"做：试点、分步推进，把抽象改革变成可执行任务。"},{"id":"a06-p5","cue":"调","summary":"反馈优化","detail":"调：收集反馈、评价效果、动态优化，而非一刀切。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A08', 'KP-A08-01', 1, '{"overview":"三种领导理论不要分别背长定义。先看题目在问哪件事：谁参与领导？领导怎么帮下属走到目标？还是领导怎么带大家改变？","points":[{"id":"a08-p1","cue":"谁","summary":"分布式领导","detail":"谁｜分布式领导：领导不是校长一个人的行为，权力与领导实践分布在多个主体，通过协作共同完成。"},{"id":"a08-p2","cue":"路","summary":"路径与目标","detail":"路｜路径—目标理论：领导者根据下属和任务特点，帮助澄清目标、扫除障碍、提供支持，使“走向目标的路”更清楚。"},{"id":"a08-p3","cue":"变","summary":"变革型领导","detail":"变｜变革型领导：通过共同愿景、激励、创新和个性化关怀，提升成员动机并推动组织变革。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A17', 'KP-A17-01', 1, '{"overview":"立德树人不是“多上一门思政课”，而是回答：学校培养什么人、用什么内容、在哪些场景育人、谁共同育人、最后如何落到学生行为。","points":[{"id":"a17-p1","cue":"向","summary":"育人方向","detail":"向：先明确育人方向：落实立德树人，培养德智体美劳全面发展的时代新人。"},{"id":"a17-p2","cue":"课","summary":"课程育人","detail":"课：发挥思政课关键课程作用，同时推进课程思政，让各学科共同育人。"},{"id":"a17-p3","cue":"行","summary":"实践认同","detail":"行：把价值教育放进社会实践、志愿服务、劳动、校园生活，让学生在行动中形成认同。"},{"id":"a17-p4","cue":"融","summary":"协同育人","detail":"融：校内校外、线上线下、家校社以及不同学段协同，形成大思政格局。"},{"id":"a17-p5","cue":"评","summary":"评价改进","detail":"评：评价不能只看分数，要关注品德、责任、实践和全面发展，并据此改进育人。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A18', 'KP-A18-01', 1, '{"overview":"健康第一不是“出了心理问题再转介”，而是把学生身体、心理、睡眠、运动、压力和校园环境放进日常学校治理。","points":[{"id":"a18-p1","cue":"健","summary":"健康日常","detail":"健：把健康放进日常：体育锻炼、睡眠、作息、减压、校园支持环境。"},{"id":"a18-p2","cue":"筛","summary":"风险识别","detail":"筛：建立日常观察、心理健康教育和风险识别，尽早发现异常信号。"},{"id":"a18-p3","cue":"支","summary":"关怀支持","detail":"支：学校提供心理辅导、班主任支持、同伴与教师关怀，减少污名化。"},{"id":"a18-p4","cue":"联","summary":"专业协作","detail":"联：对高风险情况及时联动家长、医疗和专业机构，守住安全底线。"},{"id":"a18-p5","cue":"踪","summary":"持续恢复","detail":"踪：危机后持续跟踪恢复，并根据问题改进学校制度和环境。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A12', 'KP-A12-01', 1, '{"overview":"协同不是把任务甩给家长或社会，而是先明确各自责任，再建立稳定沟通和资源联动，围绕共同育人目标合作。","points":[{"id":"a12-p1","cue":"责","summary":"职责边界","detail":"责：明确学校、家庭、社会各自职责和边界。"},{"id":"a12-p2","cue":"通","summary":"双向沟通","detail":"通：建立常态、双向、尊重的沟通机制。"},{"id":"a12-p3","cue":"联","summary":"资源联动","detail":"联：联动社区、场馆、医院、高校、社会组织等资源。"},{"id":"a12-p4","cue":"共","summary":"共同参与","detail":"共：围绕学生发展形成共同目标、共同参与、共同评价。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A19', 'KP-A19-01', 1, '{"overview":"家校社协同不是“家长来配合学校”，而是三方围绕学生发展明确边界、共享信息、互补资源、共同解决问题。","points":[{"id":"a19-p1","cue":"责","summary":"明确边界","detail":"责：先明确学校、家庭、社会的职责和边界，避免甩锅或越位。"},{"id":"a19-p2","cue":"通","summary":"常态沟通","detail":"通：建立常态、双向、尊重的沟通，不只在出问题时联系。"},{"id":"a19-p3","cue":"联","summary":"专业资源","detail":"联：联动社区、医院、高校、场馆、社会组织等专业资源。"},{"id":"a19-p4","cue":"共","summary":"共同成长","detail":"共：围绕学生成长形成共同目标、共同参与和反馈改进。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A15', 'KP-A15-01', 1, '{"overview":"教学管理不是校长天天检查教案，而是把教学目标、课堂实施、教师教研、质量评价和改进连成闭环。","points":[{"id":"a15-p1","cue":"计","summary":"目标计划","detail":"计：明确课程与教学目标，做好教学计划和组织。"},{"id":"a15-p2","cue":"教","summary":"课堂实施","detail":"教：关注课堂实施、课程落实和学生学习过程。"},{"id":"a15-p3","cue":"研","summary":"教研支持","detail":"研：通过教研、备课、听评课和专业共同体解决教学问题。"},{"id":"a15-p4","cue":"评","summary":"质量证据","detail":"评：多元收集教学质量和学习成效证据。"},{"id":"a15-p5","cue":"改","summary":"教学改进","detail":"改：根据评价结果改进课程、课堂、教师支持和资源配置。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A07', 'KP-A07-01', 1, '{"overview":"以人为本不是“什么都顺着教师和学生”，而是把人当成有需要、有尊严、有能力、能参与和能成长的主体。","points":[{"id":"a07-p1","cue":"尊","summary":"人格需要","detail":"尊：尊重人格、专业和合理需要，不把人只当执行工具。"},{"id":"a07-p2","cue":"听","summary":"倾听意见","detail":"听：倾听需求、困难和意见，建立真实沟通。"},{"id":"a07-p3","cue":"参","summary":"适度参与","detail":"参：让教师、学生在相关事务中有适度参与权。"},{"id":"a07-p4","cue":"长","summary":"促进成长","detail":"长：管理的目的之一是促进教师专业成长和学生发展。"},{"id":"a07-p5","cue":"激","summary":"激发主动","detail":"激：通过认可、授权、激励和支持激发主动性。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A10', 'KP-A10-01', 1, '{"overview":"沟通不是“我说了”就等于“对方收到了”。有效沟通至少要完成：先听、听懂、说清、再确认反馈。","points":[{"id":"a10-p1","cue":"听","summary":"获取信息","detail":"听：先获取对方真实信息、需求和情绪。"},{"id":"a10-p2","cue":"懂","summary":"理解背景","detail":"懂：理解立场和背景，避免只从管理者角度判断。"},{"id":"a10-p3","cue":"通","summary":"清晰表达","detail":"通：信息表达清晰、具体、尊重，渠道合适。"},{"id":"a10-p4","cue":"馈","summary":"确认反馈","detail":"馈：确认对方是否理解，获得反馈并及时调整。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A11', 'KP-A11-01', 1, '{"overview":"文化不是墙上的校训，而是“大家相信什么、制度奖励什么、每天怎么做、环境不断提醒什么”。","points":[{"id":"a11-p1","cue":"念","summary":"共同理念","detail":"念：共同价值、愿景和教育理念。"},{"id":"a11-p2","cue":"制","summary":"制度支持","detail":"制：制度、评价、奖励与资源配置要支持理念。"},{"id":"a11-p3","cue":"行","summary":"日常行为","detail":"行：领导和成员把理念变成日常行为。"},{"id":"a11-p4","cue":"境","summary":"环境强化","detail":"境：空间、仪式、故事、符号和氛围持续强化。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}'),
  ('A16', 'KP-A16-01', 1, '{"overview":"德育不是开几次主题班会，而是让学生知道什么是对的、在日常中做出来、被环境持续影响，并通过反馈不断强化。","points":[{"id":"a16-p1","cue":"向","summary":"价值目标","detail":"向：明确价值导向和育人目标。"},{"id":"a16-p2","cue":"行","summary":"日常实践","detail":"行：课程、班会、实践、志愿服务、日常行为养成。"},{"id":"a16-p3","cue":"境","summary":"共同育人","detail":"境：制度、教师示范、同伴关系、校园文化共同育人。"},{"id":"a16-p4","cue":"评","summary":"反馈激励","detail":"评：过程性评价、反馈、激励和改进。"}],"source":"同事体验版《考试必过版本1》A版 V3.1 教学整理"}');
